export function paintOriginalOutline(g, key, rect, fill, stroke = null) {
  const shape = ORIGINAL_OUTLINES[key];
  if (!shape) return;
  g.save();
  g.translate(rect[0] * 4.5, rect[1] * 5.4);
  g.scale((rect[2] * 4.5) / shape.size[0], (rect[3] * 5.4) / shape.size[1]);
  g.beginPath();
  for (const loop of shape.loops) {
    const first = loop[0],
      last = loop.at(-1);
    g.moveTo((last[0] + first[0]) / 2, (last[1] + first[1]) / 2);
    for (let i = 0; i < loop.length; i++) {
      const p = loop[i],
        n = loop[(i + 1) % loop.length];
      g.quadraticCurveTo(p[0], p[1], (p[0] + n[0]) / 2, (p[1] + n[1]) / 2);
    }
    g.closePath();
  }
  if (stroke) {
    g.strokeStyle = stroke;
    g.lineWidth = 0.35;
    g.stroke();
  }
  g.fillStyle = fill;
  g.fill("evenodd");
  g.restore();
}
